// Patrol City's own icon set, drawn from scratch as vector shapes on a 32x32 grid. It replaces the device's emoji
// everywhere: in the HUD and menus (DOM) and in everything painted on the canvas. Each icon is a short list of
// layers: [fill, path] or ['-stroke', path, width]. Icons are turned into Path2D once and cached as bitmaps by size,
// so drawing one costs a single drawImage.

// ---- tiny path builders
const f = (n) => Math.round(n * 10) / 10;
const R = (x, y, w, h, r = 0) => r ? `M${f(x + r)} ${f(y)}H${f(x + w - r)}A${r} ${r} 0 0 1 ${f(x + w)} ${f(y + r)}V${f(y + h - r)}A${r} ${r} 0 0 1 ${f(x + w - r)} ${f(y + h)}H${f(x + r)}A${r} ${r} 0 0 1 ${f(x)} ${f(y + h - r)}V${f(y + r)}A${r} ${r} 0 0 1 ${f(x + r)} ${f(y)}Z` : `M${x} ${y}h${w}v${h}h${-w}Z`;
const C = (x, y, r) => `M${f(x - r)} ${f(y)}a${r} ${r} 0 1 0 ${f(2 * r)} 0a${r} ${r} 0 1 0 ${f(-2 * r)} 0Z`;
const E = (x, y, rx, ry) => `M${f(x - rx)} ${f(y)}a${rx} ${ry} 0 1 0 ${f(2 * rx)} 0a${rx} ${ry} 0 1 0 ${f(-2 * rx)} 0Z`;
const P = (...p) => 'M' + p.map((q) => q.join(' ')).join('L') + 'Z';
const Lp = (...p) => 'M' + p.map((q) => q.join(' ')).join('L');
const ARC = (x, y, r, a0, a1) => { const p = (a) => [f(x + r * Math.cos(a * Math.PI / 180)), f(y + r * Math.sin(a * Math.PI / 180))]; const s = p(a0), e = p(a1); return `M${s[0]} ${s[1]}A${r} ${r} 0 ${Math.abs(a1 - a0) > 180 ? 1 : 0} 1 ${e[0]} ${e[1]}`; };

// palette
const K = '#1e293b', W = '#f8fafc', NV = '#1e3a8a', BL = '#3b82f6', SKY = '#7dd3fc', RD = '#ef4444', DR = '#b91c1c', GD = '#f5b800', YL = '#facc15', OR = '#f97316', GR = '#22c55e', DG = '#15803d',
  BR = '#92400e', TN = '#d6a76b', GY = '#94a3b8', DG2 = '#475569', PK = '#f472b6', PU = '#a855f7', SK = '#e0ac69', CR = '#fde68a', WD = '#b45309';

// ---- shared parts
const person = (shirt, skin = SK, hat) => [[shirt, 'M8 30v-6c0-4 3.6-7 8-7s8 3 8 7v6Z'], [skin, C(16, 11, 5.5)], ...(hat ? [[hat, 'M9.5 8.5c0-4 3-6 6.5-6s6.5 2 6.5 6Z'], [hat, R(8, 7.5, 16, 2.4, 1.2)]] : [])];
const car = (body, top = body, light) => [[K, C(9, 24, 3.4)], [K, C(23, 24, 3.4)], [body, R(3, 14, 26, 9, 3)], [top, 'M8 14l3-6h10l3 6Z'], [SKY, 'M10.6 13l2-4h3.2v4Zm6.6 0v-4h3.2l2 4Z'], [GY, C(9, 24, 1.4)], [GY, C(23, 24, 1.4)], ...(light ? [[RD, R(11, 4.5, 4.6, 3, 1)], [BL, R(16.4, 4.5, 4.6, 3, 1)]] : [])];
const building = (wall, roof, doorC = BR) => [[wall, R(6, 10, 20, 19)], [roof, P([4, 11], [16, 3], [28, 11])], [doorC, R(13.5, 20, 5, 9)], [SKY, R(8.5, 13, 4, 4)], [SKY, R(19.5, 13, 4, 4)]];
const book = (cover) => [[cover, R(6, 4, 20, 24, 2)], [W, R(9, 7, 14, 4, 1)], ['-' + K, Lp([10, 22], [22, 22]), 1.2]];
const paper = (lines = 3, tint = W) => [[tint, P([7, 3], [20, 3], [25, 8], [25, 29], [7, 29])], [GY, P([20, 3], [20, 8], [25, 8])], ...Array.from({ length: lines }, (_, i) => ['-' + GY, Lp([10, 13 + i * 4], [22, 13 + i * 4]), 1.6])];
const ball = (c, seam) => [[c, C(16, 16, 12)], ...(seam ? [['-' + seam, ARC(16, 16, 12, 200, 340), 1.4], ['-' + seam, ARC(16, 16, 12, 20, 160), 1.4]] : [])];
const food = (base, top, dots) => [[base, 'M4 18h24c0 6-5 10-12 10S4 24 4 18Z'], [top, E(16, 17, 12, 4)], ...(dots ? [[dots, C(11, 16, 1.6)], [dots, C(17, 18, 1.6)], [dots, C(21, 15.5, 1.6)]] : [])];
const sign = (c, sym) => [[c, R(5, 5, 22, 22, 6)], ...sym];
const face = (mouth) => [[YL, C(16, 16, 13)], [K, C(11.5, 13, 1.8)], [K, C(20.5, 13, 1.8)], ['-' + K, mouth, 2]];
const animal = (body, ear = body) => [[body, E(16, 20, 10, 8)], [body, C(16, 11, 7)], [ear, P([9, 9], [10, 2], [14, 6])], [ear, P([23, 9], [22, 2], [18, 6])], [K, C(13.5, 10, 1.2)], [K, C(18.5, 10, 1.2)], [K, E(16, 14, 1.8, 1.2)]];
const bottle = (c) => [[c, 'M12 10V5h8v5c3 2 4 4 4 7v11H8V17c0-3 1-5 4-7Z'], [W, R(10, 17, 12, 6, 1)], [GY, R(12, 3, 8, 3, 1)]];
const tree = (leaf, trunk = WD) => [[trunk, R(14, 18, 4, 11)], [leaf, C(16, 13, 10)]];
const flower = (petal, mid = YL) => [[DG, R(15, 16, 2, 13)], [petal, C(16, 7, 4)], [petal, C(10.5, 11, 4)], [petal, C(21.5, 11, 4)], [petal, C(12.5, 17, 4)], [petal, C(19.5, 17, 4)], [mid, C(16, 12, 3.4)]];
const medal = (c, rib = RD) => [[rib, P([10, 2], [16, 12], [22, 2])], [c, C(16, 20, 9)], [W, C(16, 20, 5)]];

